parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "sensibel": {
      "type": "boolean",
      "description": "true, wenn die Anfrage zu datenschutz oder hr gehört oder besondere Datenkategorien enthält. Bei Unsicherheit true. Sonst false."
    },
    "kategorie": {
      "type": "string",
      "enum": ["datenschutz", "hr", "keine"],
      "description": "Kleingeschrieben. Bei mehreren Kategorien und bei besonderen Datenkategorien ohne klares Thema datenschutz. keine nur, wenn sensibel false ist."
    },
    "begruendung": {
      "type": "string",
      "description": "Ein Satz auf Deutsch, ohne personenbezogene Daten aus der Anfrage."
    }
  },
  "required": ["sensibel", "kategorie", "begruendung"],
  "additionalProperties": false
}

